import { useState } from "react";
import NavigationLink from "./Link/NavigationLink";
import { NavigationLinkInfo } from "./Link/NavigationLinkInfo";
import "./Navigation.css";

const Navigation = () => {
  const [linksInfo, setLinksInfo] = useState<NavigationLinkInfo[]>([
    { labelText: "Home", href: "/", isActive: true },
    { labelText: "About", href: "/about", isActive: false },
    { labelText: "Contact", href: "/contact", isActive: false },
  ]);

  const setActiveLink = (href: string) => {
    setLinksInfo((prevLinks) =>
      prevLinks.map((link) => ({
        ...link,
        isActive: link.href === href,
      }))
    );
  };

  return (
    <nav className="navigation-container">
      {linksInfo.map((link, index) => (
        <NavigationLink
          key={link.href || index}
          labelText={link.labelText}
          href={link.href}
          isActive={link.isActive}
          onClick={setActiveLink}
        />
      ))}
    </nav>
  );
};

export default Navigation;
